// ---------------- Env Configuration ----------------
let envLoaded = false;

async function loadEnv(baseDir = __dirname) {
  if (envLoaded) return;
  envLoaded = true;
  const envPath = path.join(baseDir, '.env');
  try {
    const dotenvModule = await import('dotenv').catch(() => null);
    if (dotenvModule && typeof dotenvModule.config === 'function' && fs.existsSync(envPath)) {
      dotenvModule.config({ path: envPath });
      return;
    }
  } catch {
    // Fallback when dotenv package is absent
  }
  if (!fs.existsSync(envPath)) return;
  try {
    for (const line of fs.readFileSync(envPath, 'utf8').split(/\r?\n/)) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) continue;
      const eqIdx = trimmed.indexOf('=');
      if (eqIdx <= 0) continue;
      const key = trimmed.slice(0, eqIdx).trim();
      let value = trimmed.slice(eqIdx + 1).trim();
      if (
        (value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))
      ) {
        value = value.slice(1, -1);
      }
      if (!(key in process.env)) process.env[key] = value;
    }
  } catch {
    // Ignore unreadable .env
  }
}

function parseIntSetting(rawValue, fallback) {
  if (rawValue === undefined || rawValue === null || String(rawValue).trim() === '') return fallback;
  const parsed = Number.parseInt(String(rawValue).trim(), 10);
  return Number.isFinite(parsed) && parsed >= 0 ? parsed : fallback;
}

function getConfig() {
  const isProd = process.env.NODE_ENV === 'production' || Boolean(process.env.RENDER);
  const port = parseIntSetting(process.env.PORT, 3000) || 3000;
  const defaultSecondary = isProd ? 0 : 7000;
  const secondaryPort = parseIntSetting(process.env.SECONDARY_PORT, defaultSecondary);
  const rawAppUrl = (process.env.APP_URL || process.env.RENDER_EXTERNAL_URL || '').trim();
  const appUrl = rawAppUrl && !rawAppUrl.includes('MY_APP_URL') ? rawAppUrl.replace(/\/+$/, '') : '';
  const tunnelUrl = (process.env.TUNNEL_URL || '').trim().replace(/\/+$/, '');
  const debridProvider = (process.env.DEBRID_PROVIDER || 'realdebrid').trim().toLowerCase() || 'realdebrid';
  const debridApiKey = (process.env.DEBRID_API_KEY || '').trim();
  const cacheTtlSeconds = Math.max(10, parseIntSetting(process.env.CACHE_TTL_SECONDS, 300));
  const httpTimeoutMs = Math.max(500, Math.min(6000, parseIntSetting(process.env.HTTP_TIMEOUT_MS, 4500)));

  return {
    port,
    secondaryPort,
    appUrl,
    tunnelUrl,
    debridProvider,
    debridApiKey,
    cacheTtlSeconds,
    httpTimeoutMs,
  };
}

// ---------------- LRU Cache ----------------
class AddonCache {
  constructor({ maxEntries = 500, defaultTtlMs = 300_000 } = {}) {
    this.maxEntries = maxEntries;
    this.defaultTtlMs = defaultTtlMs;
    this.store = new Map();
    this.hits = 0;
    this.misses = 0;
  }

  get(key) {
    const entry = this.store.get(key);
    if (!entry) {
      this.misses++;
      return undefined;
    }
    if (Date.now() > entry.expiresAt) {
      this.store.delete(key);
      this.misses++;
      return undefined;
    }
    this.store.delete(key);
    this.store.set(key, entry);
    this.hits++;
    return entry.value;
  }

  set(key, value, ttlMs = this.defaultTtlMs) {
    if (this.store.has(key)) {
      this.store.delete(key);
    } else if (this.store.size >= this.maxEntries) {
      const oldestKey = this.store.keys().next().value;
      if (oldestKey !== undefined) this.store.delete(oldestKey);
    }
    const effectiveTtl = Math.max(1000, Number(ttlMs) || this.defaultTtlMs);
    this.store.set(key, { value, expiresAt: Date.now() + effectiveTtl });
  }

  getStats() {
    return { size: this.store.size, hits: this.hits, misses: this.misses };
  }
}

function getCacheControlHeader(resource) {
  switch (resource) {
    case 'manifest':
      return 'public, max-age=3600, stale-while-revalidate=86400';
    case 'catalog':
    case 'meta':
      return 'public, max-age=900, stale-while-revalidate=3600';
    case 'stream':
    case 'subtitles':
    default:
      return 'public, max-age=300, stale-while-revalidate=600';
  }
}

// ---------------- Bounded HTTP Client ----------------
function requestJsonNative(url, { signal, headers = {} }) {
  return new Promise((resolve, reject) => {
    const parsed = new URL(url);
    const transport = parsed.protocol === 'https:' ? https : http;
    const req = transport.request(
      parsed,
      {
        method: 'GET',
        signal,
        headers: {
          Accept: 'application/json',
          'User-Agent': 'BestPlay-Stremio-Addon/10.0',
          ...headers,
        },
      },
      (res) => {
        if (!res.statusCode || res.statusCode < 200 || res.statusCode >= 300) {
          res.resume();
          resolve(null);
          return;
        }
        const chunks = [];
        res.on('data', (chunk) => chunks.push(chunk));
        res.on('end', () => {
          try {
            const raw = Buffer.concat(chunks).toString('utf8');
            resolve(raw ? JSON.parse(raw) : null);
          } catch {
            resolve(null);
          }
        });
      }
    );
    req.on('error', reject);
    req.end();
  });
}

async function fetchJsonWithTimeout(url, { timeoutMs = 4500, headers = {}, simulateTimeout = false } = {}) {
  const effectiveTimeout = Math.max(100, Math.min(Number(timeoutMs) || 4500, 6000));
  const controller = new AbortController();
  const timer = setTimeout(
    () => controller.abort(),
    simulateTimeout ? Math.min(effectiveTimeout, 120) : effectiveTimeout
  );

  try {
    if (simulateTimeout) {
      await new Promise((_, reject) => {
        controller.signal.addEventListener(
          'abort',
          () => reject(new Error('Simulated upstream timeout via AbortController')),
          { once: true }
        );
      });
      return null;
    }
    return await requestJsonNative(url, { signal: controller.signal, headers });
  } catch (err) {
    const msg = String(err?.message || err || '').toLowerCase();
    const isSimulated = simulateTimeout || msg.includes('simulated upstream timeout');
    const isCert = msg.includes('certificate') || msg.includes('unable to verify');
    if (!isSimulated && process.platform === 'win32' && isCert) {
      try {
        const sec = String(Math.max(1, Math.min(6, Math.ceil(effectiveTimeout / 1000))));
        const { stdout } = await execFileAsync(
          'curl.exe',
          ['-sS', '-L', '--max-time', sec, '-H', 'Accept: application/json', url],
          { timeout: effectiveTimeout, maxBuffer: 2 * 1024 * 1024, windowsHide: true }
        );
        return stdout ? JSON.parse(stdout) : null;
      } catch {
        return null;
      }
    }
    return null;
  } finally {
    clearTimeout(timer);
  }
}

