// ---------------- Resource Handlers ----------------
function parseExtraParams(extraStr) {
  const result = {};
  if (!extraStr || typeof extraStr !== 'string') return result;
  try {
    const params = new URLSearchParams(extraStr);
    for (const [k, v] of params.entries()) result[k.toLowerCase()] = v;
  } catch {
    for (const segment of extraStr.split('&')) {
      const idx = segment.indexOf('=');
      if (idx > 0) {
        result[decodeURIComponent(segment.slice(0, idx)).toLowerCase()] = decodeURIComponent(segment.slice(idx + 1));
      }
    }
  }
  return result;
}

function handleCatalogRequest({ type, id, extra = '', origin, cache, cacheTtlMs }) {
  const cleanOrigin = String(origin || 'http://localhost:3000').replace(/\/+$/, '');
  const expectedId = type === 'movie' ? 'bestplay_movies' : type === 'series' ? 'bestplay_series' : null;
  if (!expectedId || id !== expectedId) {
    return { payload: { metas: [] }, cacheHit: false, cacheControl: getCacheControlHeader('catalog') };
  }

  const parsedExtra = parseExtraParams(extra);
  const cacheKey = `catalog:${cleanOrigin}:${type}:${id}:${JSON.stringify(parsedExtra)}`;
  const cached = cache.get(cacheKey);
  if (cached) {
    return { payload: cached, cacheHit: true, cacheControl: getCacheControlHeader('catalog') };
  }

  let items = CATALOG_MEDIA_ITEMS.filter((item) => item.type === type);
  if (parsedExtra.search) {
    const q = String(parsedExtra.search).trim().toLowerCase();
    items = items.filter(
      (i) => i.name.toLowerCase().includes(q) || i.description.toLowerCase().includes(q) || i.imdbId.includes(q)
    );
  }
  if (parsedExtra.genre) {
    const g = String(parsedExtra.genre).trim().toLowerCase();
    items = items.filter((i) => i.genres.some((genre) => genre.toLowerCase() === g));
  }
  const skip = Number.parseInt(parsedExtra.skip || '0', 10) || 0;
  if (skip > 0) items = items.slice(skip);

  const payload = {
    metas: items.map((item) => ({
      id: item.imdbId,
      type: item.type,
      name: item.name,
      poster: `${cleanOrigin}/logo-256.svg`,
      posterShape: 'poster',
      background: `${cleanOrigin}/background-1920.svg`,
      description: item.description,
      releaseInfo: item.releaseInfo,
      imdbRating: item.imdbRating,
      genres: item.genres,
    })),
  };
  cache.set(cacheKey, payload, cacheTtlMs);
  return { payload, cacheHit: false, cacheControl: getCacheControlHeader('catalog') };
}

const VALID_TYPES = new Set(['movie', 'series']);
const IMDB_ID_RE = /^tt\d+(?::\d+:\d+)?$/i;

async function handleMetaRequest({ type, id, origin, cache, cacheTtlMs, httpTimeoutMs }) {
  const cleanOrigin = String(origin || 'http://localhost:3000').replace(/\/+$/, '');
  const cleanId = String(id || '').trim();
  if (!VALID_TYPES.has(type) || !IMDB_ID_RE.test(cleanId)) {
    return { payload: { meta: null }, cacheHit: false, cacheControl: getCacheControlHeader('meta') };
  }

  const baseImdbId = cleanId.split(':')[0];
  const cacheKey = `meta:${cleanOrigin}:${type}:${baseImdbId}`;
  const cached = cache.get(cacheKey);
  if (cached) {
    return { payload: cached, cacheHit: true, cacheControl: getCacheControlHeader('meta') };
  }

  const localItem = CATALOG_MEDIA_ITEMS.find((i) => i.imdbId === baseImdbId && i.type === type);
  const cinemetaUrl = `https://v3-cinemeta.strem.io/meta/${encodeURIComponent(type)}/${encodeURIComponent(baseImdbId)}.json`;
  const remote = await fetchJsonWithTimeout(cinemetaUrl, {
    timeoutMs: Math.min(Number(httpTimeoutMs) || 3500, 3500),
  });
  const remoteMeta = remote && typeof remote.meta === 'object' ? remote.meta : null;

  let meta = null;
  if (localItem || (remoteMeta && remoteMeta.name)) {
    meta = {
      id: baseImdbId,
      type,
      name: String(localItem?.name || remoteMeta?.name || baseImdbId),
      poster: String(remoteMeta?.poster || `${cleanOrigin}/logo-256.svg`),
      background: String(remoteMeta?.background || `${cleanOrigin}/background-1920.svg`),
      description: String(
        localItem?.description ||
          remoteMeta?.description ||
          'Playable H.264/AVC stream & synced Greek external subtitles.'
      ),
      releaseInfo: String(localItem?.releaseInfo || remoteMeta?.releaseInfo || ''),
      imdbRating: String(localItem?.imdbRating || remoteMeta?.imdbRating || '8.0'),
      runtime: String(localItem?.runtime || remoteMeta?.runtime || ''),
      genres:
        Array.isArray(localItem?.genres) && localItem.genres.length > 0
          ? localItem.genres
          : Array.isArray(remoteMeta?.genres)
            ? remoteMeta.genres
            : ['Drama'],
    };
    if (Array.isArray(remoteMeta?.videos) && remoteMeta.videos.length > 0) {
      meta.videos = remoteMeta.videos;
    }
  }

  const payload = { meta };
  if (meta !== null) cache.set(cacheKey, payload, cacheTtlMs);
  return { payload, cacheHit: false, cacheControl: getCacheControlHeader('meta') };
}

const PREBUILT_BESTPLAY_SAFE_P2P_BASE =
  'https://aiostreamsfortheweebs.midnightignite.me/stremio/82916bd8-8215-48bd-a66c-41d487150d51/eyJpIjoiWXdicWYrcDFvRDBWbkFBTE1Cc0MzQT09IiwiZSI6Ii9XVk1RYnVBMFBmWVFCVEoxaENPNFZodFRpWmNLK3pKT1d1eUhIenc2VTRvKzFQV2tHa0ZPYVk1OTlHVFl2cHQiLCJ0IjoiYSJ9';

const UNPLAYABLE_PATTERN =
  /\b(x265|hevc|h\.?265|h\.?266|vvc|av1|10bit|hi10|truehd|dts|hardcoded|hardsub|hc-?sub|korsub|burned|exyusubs)\b|\.(avi|wmv|flv|m2ts|iso)\b/i;

function parseAddonConfigSegment(configStr, envConfig = {}) {
  const defaults = {
    debridProvider: envConfig.debridProvider || 'realdebrid',
    apiKey: envConfig.debridApiKey || '',
  };
  if (!configStr || typeof configStr !== 'string') return defaults;
  let decoded = configStr;
  try {
    decoded = decodeURIComponent(configStr);
  } catch {}
  if (!decoded.includes('=') || !decoded.includes('|')) {
    try {
      const fromB64 = Buffer.from(decoded, 'base64').toString('utf8');
      if (fromB64.includes('=') || fromB64.includes('|')) decoded = fromB64;
    } catch {}
  }
  const parsed = { ...defaults };
  for (const part of decoded.split('|')) {
    const eqIndex = part.indexOf('=');
    if (eqIndex <= 0) continue;
    const cleanKey = part.slice(0, eqIndex).trim().toLowerCase();
    const cleanVal = part.slice(eqIndex + 1).trim();
    if (!cleanKey || !cleanVal) continue;
    if (['realdebrid', 'alldebrid', 'premiumize', 'torbox'].includes(cleanKey)) {
      parsed.debridProvider = cleanKey;
      parsed.apiKey = cleanVal;
    }
  }
  return parsed;
}

function sanitizePlayableStreams(streams, requireDirectUrl) {
  if (!Array.isArray(streams)) return [];
  const valid = [];
  for (const s of streams) {
    if (!s || typeof s !== 'object') continue;
    if (s.externalUrl || s.streamData?.type === 'statistic') continue;
    if (requireDirectUrl ? !s.url : !(s.url || s.infoHash)) continue;
    const filename = s.behaviorHints?.filename ? String(s.behaviorHints.filename) : '';
    const inspectText = `${s.name || ''} ${s.title || ''} ${s.description || ''} ${filename}`;
    if (UNPLAYABLE_PATTERN.test(inspectText)) continue;
    const normalized = {
      name: String(s.name || 'BestPlay · 1080p AVC').trim(),
      title: String(s.title || s.description || filename || '1080p H.264 Playable Stream').trim(),
      behaviorHints: { ...(s.behaviorHints && typeof s.behaviorHints === 'object' ? s.behaviorHints : {}) },
    };
    if (s.url) normalized.url = String(s.url);
    if (s.infoHash) normalized.infoHash = String(s.infoHash);
    if (typeof s.fileIdx === 'number') normalized.fileIdx = s.fileIdx;
    if (Array.isArray(s.sources) && s.sources.length > 0) normalized.sources = s.sources;
    valid.push(normalized);
  }
  return valid;
}

async function handleStreamRequest({
  type,
  id,
  configStr = '',
  origin,
  envConfig,
  cache,
  cacheTtlMs,
  httpTimeoutMs,
  simulateTimeout = false,
}) {
  const cleanOrigin = String(origin || 'http://localhost:3000').replace(/\/+$/, '');
  const cleanId = String(id || '').trim();
  if (!VALID_TYPES.has(type) || !IMDB_ID_RE.test(cleanId)) {
    return { payload: { streams: [] }, cacheHit: false, cacheControl: getCacheControlHeader('stream') };
  }

  const parsedConfig = parseAddonConfigSegment(configStr, envConfig);
  const hasDebrid = Boolean(parsedConfig.apiKey && !parsedConfig.apiKey.includes('YOUR_'));
  const cacheKey = `stream:${cleanOrigin}:${hasDebrid ? parsedConfig.debridProvider : 'web'}:${type}:${cleanId}`;
  if (!simulateTimeout) {
    const cached = cache.get(cacheKey);
    if (cached) {
      return { payload: cached, cacheHit: true, cacheControl: getCacheControlHeader('stream') };
    }
  }

  const baseImdbId = cleanId.split(':')[0];
  const catalogItem = CATALOG_MEDIA_ITEMS.find((m) => m.imdbId === cleanId || m.imdbId === baseImdbId);
  const releaseTitle = catalogItem?.releaseTitle || `${baseImdbId}.1080p.WEB-DL.H264.AAC2.0-BestPlay.mp4`;

  const webReadyStream = {
    name: 'BestPlay ⚡\n1080p AVC Safe',
    title: `${releaseTitle}\nAAC 2.0 · Playable Only · Direct HTTPS`,
    url: `${cleanOrigin}/api/sample-stream.mp4`,
    behaviorHints: {
      notWebReady: false,
      bingeGroup: 'bestplay-safe-avc',
      filename: releaseTitle,
    },
  };

  const upstreamBase = hasDebrid
    ? `https://torrentio.strem.fun/${[
        'providers=yts,eztv,1337x,torrentgalaxy,thepiratebay,rarbg',
        'sort=qualityseeders',
        'qualityfilter=4k,brremux,hdrall,dolbyvision,dolbyvisionwithhdr,threed,480p,other,scr,cam',
        'limit=2',
        'debridoptions=nodownloadlinks,nocatalog',
        `${parsedConfig.debridProvider}=${parsedConfig.apiKey}`,
      ].join('|')}`
    : PREBUILT_BESTPLAY_SAFE_P2P_BASE;

  const data = await fetchJsonWithTimeout(
    `${upstreamBase}/stream/${encodeURIComponent(type)}/${encodeURIComponent(cleanId)}.json`,
    { timeoutMs: Math.min(Number(httpTimeoutMs) || 4500, 4500), simulateTimeout }
  );
  const upstreamStreams = sanitizePlayableStreams(data?.streams, hasDebrid).slice(0, 2);

  const streams = hasDebrid
    ? upstreamStreams.length > 0
      ? upstreamStreams
      : [webReadyStream]
    : [webReadyStream, ...upstreamStreams];

  const payload = { streams };
  if (!simulateTimeout) cache.set(cacheKey, payload, cacheTtlMs);
  return { payload, cacheHit: false, cacheControl: getCacheControlHeader('stream') };
}

